    for char in dancing_brigade:
        if char.isupper():
            mother_children[char] = []
        else:
            # Find which mother this child belongs to
            mother = char.upper()
            if mother in mother_children:
                mother_children[mother].append(char)

    # Second pass: build result
    result = []
    # Sort mothers alphabetically
    sorted_mothers = sorted(mother_children.keys())

    for mother in sorted_mothers:
        # Add mother first
        result.append(mother)
        # Add all children of this mother, sorted
        children = sorted(mother_children[mother])
